// План specs/billing-trial.md, 1.1 (кейс BT-07). Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage, openPlansTab } from '../admin-plans/plans-helpers';
import { accountRows, columnValues, filterControl, selectFilter, expectColumnEqualsOrEmpty, EMPTY_EN, FILTER } from '../admin-plans/plans-read-helpers';

test.use({ storageState: '../auth/admin.json' });

const DAY = 24 * 60 * 60 * 1000;

test.describe('Trial — Admin Panel → Plans', () => {
  test('Active trial rows end within 7 days from today #f109cde8 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');
    await openPlansTab(page);
    await expect(accountRows(page).first()).toBeVisible();

    await selectFilter(page, filterControl(page, FILTER.sources), 'Trial');
    await selectFilter(page, filterControl(page, FILTER.statuses), 'Trial');
    await expectColumnEqualsOrEmpty(page, 'Source', 'Trial');
    await expectColumnEqualsOrEmpty(page, 'Subscription status', 'Trial');

    if (await page.getByText(EMPTY_EN, { exact: true }).isVisible()) {
      test.info().annotations.push({ type: 'note', description: 'Активных trial сегодня нет — проверять нечего.' });
      return;
    }

    // «Сегодня» — в часовом поясе браузера, как сайт показывает даты (полночь UTC той же календарной даты).
    const today = await page.evaluate(() => {
      const d = new Date();
      return Date.UTC(d.getFullYear(), d.getMonth(), d.getDate());
    });

    const untilValues = await columnValues(page, 'Until');
    expect(untilValues.length).toBeGreaterThan(0);
    const bad: string[] = [];
    for (const v of untilValues) {
      // Формат EN: «Oct 15, 2026».
      const m = v.match(/^([A-Z][a-z]{2}) (\d{1,2}), (\d{4})$/);
      if (!m) { bad.push(`${v} — не дата`); continue; }
      const parsed = new Date(`${m[1]} ${m[2]}, ${m[3]}`);
      const until = Date.UTC(parsed.getFullYear(), parsed.getMonth(), parsed.getDate());
      const days = Math.round((until - today) / DAY);
      if (days < 0 || days > 7) bad.push(`${v} — ${days} дн. от сегодня`);
    }
    expect(bad, 'Until активного trial должен быть в пределах 0…7 дней от сегодня').toEqual([]);
  });
});
